def solid_rects(grid, minside, maxside=30):
    """Top-left anchored maximal solid-color rectangles (nonzero color) with height and width >= minside."""
    H, W = len(grid), len(grid[0])
    res = []
    for i0 in range(H):
        for j0 in range(W):
            c = grid[i0][j0]
            if c == 0:
                continue
            w = 0
            while j0 + w < W and grid[i0][j0 + w] == c:
                w += 1
            h = 0
            while i0 + h < H and all(grid[i0 + h][j0 + k] == c for k in range(w)):
                h += 1
            if minside <= h <= maxside and minside <= w <= maxside:
                res.append((i0, i0 + h - 1, j0, j0 + w - 1, c))
    return res

