add='''

def clean_rects(grid, minh=1, minw=1):
    """Maximal solid-color rectangles that cannot be extended in any direction (planted rects)."""
    H, W = len(grid), len(grid[0])
    res = set()
    for i0 in range(H):
        for j0 in range(W):
            c = grid[i0][j0]
            if c == 0:
                continue
            wmax = 0
            for i1 in range(i0, H):
                w = 0
                while j0 + w < W and grid[i1][j0 + w] == c:
                    w += 1
                wmax = w if i1 == i0 else min(wmax, w)
                if wmax == 0:
                    break
                h = i1 - i0 + 1
                if h >= minh and wmax >= minw:
                    ext = (i0 > 0 and all(grid[i0-1][j] == c for j in range(j0, j0+wmax))) or \
                          (i1 < H-1 and all(grid[i1+1][j] == c for j in range(j0, j0+wmax))) or \
                          (j0 > 0 and all(grid[i][j0-1] == c for i in range(i0, i1+1))) or \
                          (j0+wmax < W and all(grid[i][j0+wmax] == c for i in range(i0, i1+1)))
                    if not ext:
                        res.add((i0, i1, j0, j0+wmax-1, c))
    return sorted(res)
'''
